VALUES ('zhou-guo-wugong', '武公', ARRAY[]::text[], '姬', NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '西周惠公长子，承惠公为西周国君，文公之父。《史记·周本纪》及《史记集解》引徐广注可证其世系，但未载本名；部分后世君主表称其名共之，出处未详。在位起讫年无可靠记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西周武公"}]'::jsonb, '武公', NULL, '武公')
